   "sintesis": "Los pacientes afiliados que se desplacen a Lima, Callao, Lambayeque, Cajamarca, Cusco y Ucayali podrán recibir atención en los establecimientos de salud durante las actividades programadas del sumo pontífice. Ante el desplazamiento de ciudadanos por la visita del papa León XIV al Perú , del 11 al 16 de noviembre, el Ministerio de Salud (Minsa), a través del Seguro Integral de Salud ( SIS ), informó que todos sus afiliados cuentan con cobertura de salud garantizada a nivel nacional, sin importar su lugar de residencia.",
